def main():
    out = Path('data/z52d/avenue/rank_A')
    sample = [json.loads(l) for l in (out/'negative_sample.jsonl').read_text().splitlines()]
    assert len(AUDIT) == 40 and {a[0] for a in AUDIT} == {r['mid'] for r in sample}
    rows = [dict(mid=m, verdict_ok=v, why=w, should_be=s) for m,v,w,s in AUDIT]
    (out/'negaudit.jsonl').write_text(''.join(json.dumps(r, ensure_ascii=False)+'\n' for r in rows))
    by_mid = {r['mid']:r for r in rows}
    stats = json.loads((out/'selection.json').read_text())
    for kind, pred in [('strict_overturn',lambda v:v is False), ('including_partial',lambda v:v is not True)]:
        raw = sum(pred(r['verdict_ok']) for r in rows)
        weighted = 0
        for batch, st in stats['strata'].items():
            hit = sum(pred(by_mid[r['mid']]['verdict_ok']) for r in sample if r['batch']==batch)
            weighted += st['population']*hit/st['sample']
        print(kind, raw, '/40 =', raw/40, 'stratum-weighted=', weighted/stats['negative_population'])


if __name__ == '__main__':
    main()
